(388587,388855,1,$q$在下列有关数字图像与图形的叙述中，错误的是____。$q$,$q$B$q$,$q$GIF 采用无损压缩，说“有损压缩”错误。故选 B。$q$,$q${"A": "取样图像的数字化过程，一般分为扫描、分色、取样和量化等处理步骤", "B": "为了使网页传输的图像数据尽可能少，常用的 GIF 格式图像文件采用了有损压缩", "C": "矢量图形（简称图形）是指使用计算机技术合成的图像", "D": "计算机辅助设计和计算机动画是计算机合成图像的典型应用"}$q$,$q${"titleContent": "在下列有关数字图像与图形的叙述中，错误的是____。", "analyze": "GIF 采用无损压缩，说“有损压缩”错误。故选 B。", "correct": null, "questionItemObjects": [{"prefix": "A", "content": "取样图像的数字化过程，一般分为扫描、分色、取样和量化等处理步骤<br/>取样图像的数字化过程一般分为扫描、分色和成像。由于图像识别失败，不能尽可能小常用的GIF格式图像文件采用了有损压缩", "itemUuid": "c7d72d63295544c99e7bbf15745725dc", "score": null}, {"prefix": "B", "content": "为了使网页传输的图像数据尽可能少,常用的OH格式图像可以忽略。", "itemUuid": "70b142ec637c4468a189103eb5cec1b2", "score": null}, {"prefix": "C", "content": "矢量图形（简称图形）是指使用计算机技术合成的图像", "itemUuid": "c807a5232a074cbbac7a3d99de867f7d", "score": null}, {"prefix": "D", "content": "计算机辅助设计和计算机动画是计算机合成图像的典型应用", "itemUuid": "b2842c1262b94e6ebe5df03b06dfa480", "score": null}]}$q$);
UPDATE t_question q SET question_type=e.qtype, stem=e.stem, correct=e.correct, analysis=e.analysis,
  option_json=coalesce(e.options,q.option_json), qc_grade='good', answer_check='match'
FROM p11 e WHERE q.id=e.id AND NOT q.is_golden;
UPDATE t_text_content t SET content=e.content FROM p11 e WHERE t.id=e.tc_id;
DO $$ DECLARE n int; BEGIN
 SELECT count(*) INTO n FROM t_question q JOIN p11 e ON e.id=q.id
  WHERE q.question_type=e.qtype AND q.stem=e.stem AND q.correct=e.correct AND q.analysis=e.analysis
    AND q.qc_grade='good' AND q.answer_check='match'
    AND (e.options IS NULL OR q.option_json=e.options);
 IF n<>11 THEN RAISE EXCEPTION '更新应为11，实际%',n; END IF;
 SELECT count(*) INTO n FROM t_text_content t JOIN p11 e ON t.id=e.tc_id WHERE t.content=e.content AND pg_input_is_valid(t.content,'json');
 IF n<>11 THEN RAISE EXCEPTION '文本应为11，实际%',n; END IF;
 SELECT count(*) INTO n FROM practice_answer WHERE question_id IN (336063,340736,348943,349359,355155,357384,357811,357855,363735,375627,388587); IF n<>0 THEN RAISE EXCEPTION '有作答'; END IF;
 SELECT count(*) INTO n FROM t_question WHERE NOT deleted; IF n<>44390 THEN RAISE EXCEPTION '活跃数'; END IF;
 SELECT count(*) INTO n FROM t_question WHERE is_golden; IF n<>200 THEN RAISE EXCEPTION '金标数'; END IF;
END $$;
COMMIT;
